import java.util.*;

class Solution {
    public int diagonalSum(int[][] mat) {
        int n = mat.length;
        int sum = 0;
        for (int i = 0; i < n; i++) {
            sum += mat[i][i];            // main diagonal
            sum += mat[i][n - 1 - i];    // other diagonal
        }
        if (n % 2 == 1) {
            sum -= mat[n / 2][n / 2];    // centre was added twice
        }
        return sum;
    }
}

